add_action( 'woocommerce_after_checkout_form', 'perfectpixel_no_default_payment_method' );

function perfectpixel_no_default_payment_method() {
	?>
	<script>
	jQuery( function ( $ ) {
		var chosen = false;
		$( document.body ).on( 'change', 'input[name="payment_method"]', function ( e ) {
			if ( e.originalEvent ) {
				chosen = true;
			}
		} );
		$( document.body ).on( 'updated_checkout', function () {
			if ( chosen ) {
				return;
			}
			$( 'input[name="payment_method"]' ).prop( 'checked', false );
			$( '.payment_box' ).hide();
		} );
	} );
	</script>
	<?php
}
